insert into chart_templates
  (country, code, name, name_i18n, is_default, audience, statements,
   certification_status, legal_reference, source_key)
values
  ('MD', 'default', 'Planul general de conturi contabile', '{"en":"General chart of accounts"}'::jsonb, true, 'companies', array['MD-SNC-BS', 'MD-SNC-IS']::text[], null, 'Ordinul Ministerului Finanțelor nr. 119 din 06.08.2013, în vigoare de la 01.01.2014, obligatoriu de la 01.01.2015 pentru entitățile care nu aplică Standardele Internaționale de Raportare Financiară și nu sunt instituții publice — Planul general de conturi contabile, cu nouă clase (1-9). Acest pachet transcrie clasele 1-7 (active imobilizate, active circulante, capital propriu, datorii pe termen lung, datorii curente, venituri, cheltuieli), care poartă conturile de bilanț și de rezultate; clasa 8 (conturi de gestiune) și clasa 9 (conturi extrabilanțiere), declarate de recomandare de textul ordinului și fără corespondent în Declarația privind TVA sau în situațiile financiare, nu sunt reluate — a se vedea README.md. Subconturile 53441 și 53442 (TVA colectată/deductibilă) sunt o convenție a acestui pachet pentru a distinge contul de decontare a TVA (5344, reconciliabil) de conturile de postare ale taxelor, absentă din nomenclatorul oficial care nu detaliază contul 5344 la gradul II — semnalată în README.', 'omf119-2013')
on conflict (country, code) do update set
  name                 = excluded.name,
  name_i18n            = excluded.name_i18n,
  is_default           = excluded.is_default,
  audience             = excluded.audience,
  statements           = excluded.statements,
  certification_status = excluded.certification_status,
  legal_reference      = excluded.legal_reference,
  source_key           = excluded.source_key;

