values
  ('MD', 'MD-P-20', 'Procurări pe teritoriul țării — cota standard 20%, deductibilă', '{"en":"Domestic purchases — standard rate 20%, deductible"}'::jsonb, null, 'percent', 20, 'purchase', 'domestic', date '2016-01-01', null, 'Codul fiscal, art. 102 alin. (1) — subiecților impozabili înregistrați li se permite trecerea în cont a sumei TVA achitate sau care urmează a fi achitată furnizorilor plătitori de TVA pe valorile materiale, serviciile procurate pentru efectuarea livrărilor impozabile, dacă dispun de factura fiscală a furnizorului (art. 102 alin. (6) lit. a)).', null, null, 50, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('MD', 'MD-P-8', 'Procurări pe teritoriul țării — cota redusă 8%, deductibilă', '{"en":"Domestic purchases — reduced rate 8%, deductible"}'::jsonb, null, 'percent', 8, 'purchase', 'domestic', date '2023-12-31', null, 'Codul fiscal, art. 96 lit. b) pentru cota aplicată de furnizor; art. 102 alin. (1) pentru dreptul de trecere în cont al cumpărătorului, în aceleași condiții ca la MD-P-20.', null, null, 60, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('MD', 'MD-P-IMPORT', 'Import de mărfuri — cota standard 20%, deductibilă', '{"en":"Import of goods — standard rate 20%, deductible"}'::jsonb, null, 'percent', 20, 'purchase', 'import', date '2016-01-01', null, 'Codul fiscal, art. 100 — valoarea impozabilă a mărfurilor importate este valoarea lor vamală; art. 101 alin. (7) — TVA se achită pînă la sau la momentul depunerii declarației vamale; art. 102 alin. (6) lit. b) — trecerea în cont este condiționată de documentul eliberat de autoritățile vamale ce confirmă achitarea TVA la mărfurile importate.', null, null, 70, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('MD', 'MD-P-IMPORT-SRV', 'Import de servicii — autolichidare, cota standard 20%', '{"en":"Import of services — self-assessment, standard rate 20%"}'::jsonb, null, 'percent', 20, 'purchase', 'foreign_services_received', date '2016-01-01', null, 'Codul fiscal, art. 94 lit. c) — persoana care importă servicii pentru desfășurarea activității de întreprinzător este subiect impozabil; art. 101 alin. (4) — TVA se achită la momentul achitării plății pentru serviciul importat; art. 115 alin. (1) — obligația de a declara TVA aferentă serviciilor importate pentru fiecare perioadă fiscală, chiar și de o persoană neînregistrată ca plătitor de TVA.', null, null, 80, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('MD', 'MD-S-0-EXPORT', 'Export de mărfuri, servicii și transport internațional — cota zero', '{"en":"Export of goods, services and international transport — zero rate"}'::jsonb, null, 'percent', 0, 'sale', 'export', date '2008-01-01', null, 'Codul fiscal, art. 104 lit. a) — se impozitează la cota zero a TVA mărfurile, serviciile pentru export și toate tipurile de transporturi internaționale de mărfuri (inclusiv de expediție) și pasageri; art. 102 alin. (8) — dreptul la restituirea TVA aferente valorilor materiale, serviciilor procurate pentru o astfel de livrare este condiționat de confirmarea organelor vamale privind livrarea mărfurilor pentru export și de documentele de transport internațional.', null, null, 30, 'vat', true, array['transport_evidence']::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('MD', 'MD-S-20', 'Livrări — cota standard 20%', '{"en":"Sales — standard rate 20%"}'::jsonb, null, 'percent', 20, 'sale', 'domestic', date '2016-01-01', null, 'Codul fiscal, art. 96 lit. a) — cota standard, în mărime de 20% din valoarea impozabilă a livrărilor efectuate pe teritoriul Republicii Moldova.', null, null, 10, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null),
  ('MD', 'MD-S-8', 'Livrări — cota redusă 8%', '{"en":"Sales — reduced rate 8%"}'::jsonb, null, 'percent', 8, 'sale', 'domestic', date '2023-12-31', null, 'Codul fiscal, art. 96 lit. b) — cotă redusă de 8%, aplicabilă, printre altele: pîinii și produselor de panificație și laptelui și produselor lactate (cu excepția produselor alimentare pentru copii, scutite conform art. 103 alin. (1) pct. 2)); medicamentelor înscrise în Nomenclatorul de stat sau autorizate de Ministerul Sănătății, inclusiv preparate în farmacii conform prescripțiilor magistrale; unor mărfuri și articole cu destinație medicală de la pozițiile tarifare indicate expres de lege; gazelor naturale și gazelor lichefiate; producției din zootehnie și horticultură în formă naturală, livrate de producători; zahărului din sfeclă de zahăr; biocombustibilului solid; produselor de igienă feminină de la poziția tarifară ex. 9619; serviciilor de cazare, indiferent de categoria de confort, și produselor alimentare și/sau băuturilor nealcoolice preparate sau nepreparate, însoțite de servicii ce permit consumul imediat, în cadrul activităților din secțiunea I a Clasificatorului Activităților din Economia Moldovei (domeniul HORECA) — cota de 8% aplicabilă domeniului HORECA este permanentă începînd cu 31 decembrie 2023, dată la care a încetat starea de urgență ce menținea temporar o cotă redusă la 8% din 2022, potrivit modificării aduse prin Legea nr. 212/2023.', null, null, 20, 'vat', true, '{}'::tax_condition[], null, false, false, null, 'sfs-horeca-8', null, null, null, null),
  ('MD', 'MD-S-EXE', 'Livrare scutită de TVA fără drept de deducere — locuință, pămînt, arendă', '{"en":"Exempt supply without right of deduction — housing, land, lease"}'::jsonb, null, 'percent', 0, 'sale', 'exempt', date '2016-01-01', null, 'Codul fiscal, art. 103 alin. (1) pct. 1) — T.V.A. nu se aplică livrărilor de mărfuri, servicii ce constituie rezultatul activității de întreprinzător, printre care locuința, pămîntul, arenda acestora, dreptul de livrare și arendare a acestora, cu excepția plăților de comision aferente tranzacțiilor respective.', null, null, 40, 'vat', true, array['supply_nature']::tax_condition[], null, false, false, null, 'codul-fiscal', null, null, null, null)
on conflict (country, code) do update set
  name            = excluded.name,
  name_i18n       = excluded.name_i18n,
  description     = excluded.description,
  amount_type     = excluded.amount_type,
  amount          = excluded.amount,
  applies_to      = excluded.applies_to,
  treatment       = excluded.treatment,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  vat_category    = excluded.vat_category,
  exemption_code  = excluded.exemption_code,
  sequence        = excluded.sequence,
  tax_kind        = excluded.tax_kind,
  recoverable     = excluded.recoverable,
  conditions      = excluded.conditions,
  jurisdiction    = excluded.jurisdiction,
  price_include   = excluded.price_include,
  cash_basis      = excluded.cash_basis,
  cash_basis_transition_account_code = excluded.cash_basis_transition_account_code,
  source_key      = excluded.source_key,
  applies_seller_territory = excluded.applies_seller_territory,
  applies_buyer_territory  = excluded.applies_buyer_territory,
  applies_supply_territory = excluded.applies_supply_territory,
  applies_supply_vs_seller = excluded.applies_supply_vs_seller;

