    ('MD-P-IMPORT-SRV', 'credit_note', 'tax', 100, '53443', '8', array['8']::text[], -100, 'MD-TVA12', 20),
    ('MD-S-0-EXPORT', 'invoice', 'base', 100, null, '5', array['5']::text[], 100, 'MD-TVA12', 10),
    ('MD-S-0-EXPORT', 'credit_note', 'base', 100, null, '5', array['5']::text[], -100, 'MD-TVA12', 10),
