insert into tax_report_templates
  (country, code, name, periods, period_default, valid_from, valid_to, legal_reference,
   is_periodic_return, deadline_rule, deadline_day, deadline_plus_days,
   deadline_reference, deadline_source_key, file_format)
values
  ('MD', 'MD-TVA12', 'Declarația privind TVA (forma TVA12)', array['month']::declaration_period[], 'month'::declaration_period, date '2012-10-25', null, 'Ordinul Inspectoratului Fiscal Principal de Stat nr. 1164 din 25.10.2012, anexa nr. 1 (formularul TVA12) și anexa nr. 2 (Modul de completare). Acest pachet transcrie boxele pe care taxele sale le declară și cele patru totaluri pe care le poate calcula fără starea din perioada fiscală precedentă; sub-boxele 1.1, 2.1 și 11.1 (informative, nu se completează sau condiționate de un avans încasat în altă perioadă decît livrarea) și boxele 17, 21, 22 (suma trecută în cont din perioada precedentă, suma destinată trecerii în cont în perioada următoare, suma solicitată spre restituire) nu sunt reluate — a se vedea README.md și secțiunea «From Moldova» din docs/international.md.', true,'day_of_month_after_period'::filing_deadline_rule, 25, null, 'Codul fiscal, art. 115 alin. (1) — declarația privind TVA se prezintă Serviciului Fiscal de Stat pentru fiecare perioadă fiscală, în termenul stabilit de acest articol. Cercetarea acestui pachet nu a putut confirma formularea la zi a art. 115 alin. (1) pe un text consolidat deschis fără autentificare (legis.md refuză o cerere fără navigator, ca Légifrance — a se vedea docs/packs.md); practica de raportare curentă (formularul TVA12, prezentat prin SIA „Declarație electronică”) fixează termenul la ziua 25 a lunii următoare încheierii perioadei fiscale, dată reținută aici — de reverificat pe textul oficial de un contabil autorizat.', 'sfs-raportare-portal', null)
on conflict (country, code) do update set
  name                = excluded.name,
  periods             = excluded.periods,
  period_default      = excluded.period_default,
  valid_from          = excluded.valid_from,
  valid_to            = excluded.valid_to,
  legal_reference     = excluded.legal_reference,
  is_periodic_return  = excluded.is_periodic_return,
  deadline_rule       = excluded.deadline_rule,
  deadline_day        = excluded.deadline_day,
  deadline_plus_days  = excluded.deadline_plus_days,
  deadline_reference  = excluded.deadline_reference,
  deadline_source_key = excluded.deadline_source_key,
  file_format         = excluded.file_format;

