  ('MD', 'MD-TVA12', '8', 'tax', 'Suma TVA calculată de la valoarea de la rd. 7', '{"en":"VAT calculated on the value from row 7"}'::jsonb, 80, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul TVA12, rd. 8; Modul de completare, pct. 4.10.', 'oifps-1164-2012'),
  ('MD', 'MD-TVA12', '9', 'tax', 'Ajustarea TVA aferentă livrărilor', '{"en":"Adjustment of VAT related to supplies"}'::jsonb, 90, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul TVA12, rd. 9; Modul de completare, pct. 4.11 — corectarea erorilor din perioadele precedente, datoriile compromise (art. 116 alin. (1)) și ajustările conform art. 98 pentru livrările efectuate.', 'oifps-1164-2012'),
  ('MD', 'MD-TVA12', '10', 'total', 'Total — volumul livrărilor efectuate în perioada fiscală', '{"en":"Total — volume of supplies made in the fiscal period"}'::jsonb, 100, null, array['1', '3', '5', '6']::text[], '{}'::text[], null, null, false, false, null, 'Formularul TVA12, rd. 10; Modul de completare, pct. 4.12.', 'oifps-1164-2012'),
