  ('MD', 'MD-TVA12', '12', 'base', 'Procurări de mărfuri, servicii pe teritoriul Republicii Moldova', '{"en":"Purchases of goods, services on the territory of the Republic of Moldova"}'::jsonb, 120, null, '{}'::text[], '{}'::text[], null, null, false, false, null, 'Formularul TVA12, rd. 12; Modul de completare, pct. 4.15.', 'oifps-1164-2012'),
