  ('MD', 'MD-TVA12', '20', 'total', 'TVA aferentă bugetului pentru import de servicii', '{"en":"VAT due to the budget for the import of services"}'::jsonb, 190, null, array['8']::text[], '{}'::text[], null, null, false, false, null, 'Formularul TVA12, rd. 20 (echivalentă cu suma reflectată la rd. 8); Modul de completare, pct. 4.23.', 'oifps-1164-2012')
