insert into statement_templates
  (code, country, chart_code, name, kind, framework, valid_from, valid_to, legal_reference,
   source_key)
values
  ('MD-SNC-BS', 'MD', 'default', 'Bilanțul contabil', 'balance_sheet', 'MD-SNC-5', date '1970-01-01', null, 'S.N.C. 5 „Prezentarea situațiilor financiare”, aprobat prin ordinul Ministerului Finanțelor nr. 118 din 29.07.2013, anexa nr. 1 — Forma nr. 1, Bilanțul contabil. Acest pachet transcrie liniile de capitol și de secțiune ale formularului, la nivelul grupelor de conturi (cod rd.), fără fiecare cont sintetic de gradul I sau II în parte — forma abreviată, în lipsa unei versiuni oficiale «micro» sau «prescurtate» distincte confirmate de cercetarea acestui pachet. Activele biologice imobilizate (clasa 13), introduse ulterior primei redacții a formularului consultate, sunt reluate împreună cu activele materiale pe termen lung (rd. 090) — a se vedea README.md.', 'snc-prezentarea'),
  ('MD-SNC-IS', 'MD', 'default', 'Raportul de profit și pierderi', 'income_statement', 'MD-SNC-5', date '1970-01-01', null, 'S.N.C. 5 „Prezentarea situațiilor financiare”, anexa nr. 2 — Forma nr. 2, Raportul de profit și pierderi, în varianta pe funcții (cheltuieli clasificate în costul vânzărilor, cheltuieli de distribuire, cheltuieli administrative și alte cheltuieli operaționale). Veniturile și cheltuielile din conturile 613, 616-618 și, respectiv, 715-718, care nu figurau pe un rând distinct al primei redacții a formularului consultate, sunt reluate împreună cu «alte venituri operaționale» (rd. 040) și «alte cheltuieli operaționale» (rd. 070) — a se vedea README.md.', 'snc-prezentarea')
on conflict (code) do update set
  country         = excluded.country,
  chart_code      = excluded.chart_code,
  name            = excluded.name,
  kind            = excluded.kind,
  framework       = excluded.framework,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference,
  source_key      = excluded.source_key;

