update country_defaults set
  numbering_gapless             = true,
  number_format                 = '{CODE}{NNNNNNN}',
  legal_payment_days            = null,
  late_payment_reference        = 'Codul civil, art. 942 alin. (1)-(2) — dacă o sumă de bani nu este plătită la scadență, creditorul are dreptul la dobânda de întârziere asupra acestei sume din ziua imediat următoare datei scadenței pînă în ziua plății, la rata prevăzută de acest articol (rata de bază stabilită semianual de Banca Națională a Moldovei, majorată cu un număr de puncte procentuale), fie la o altă rată prevăzută de dispoziții legale speciale sau de contract. Dispozițiile art. 942-945, introduse prin Legea nr. 133/2018, se aplică de la 1 martie 2019. Codul fiscal nu fixează un termen de plată implicit între profesioniști, spre deosebire de Directiva europeană 2011/7/UE: termenul rămîne o clauză a contractului.',
  numbering_legal_reference     = 'Codul fiscal, art. 117 alin. (2) pct. 1) — factura fiscală trebuie să includă în mod obligatoriu «numărul curent al facturii». Legea cere doar un număr curent (secvențial), fără să impute o remitere la zero anuală; seria facturii fiscale este fie atribuită de Serviciul Fiscal de Stat pentru un formular imprimat tipografic, fie autoimprimată cu o serie și un număr alocate de acesta, potrivit art. 117 și normelor de completare aprobate prin ordinul Ministerului Finanțelor nr. 118 din 28.08.2017 — formatul indicat aici, cu un cod de serie și un contor, este un exemplu de conformare al acestui pachet și nu forma unică impusă de text.',
  numbering_source_key          = 'codul-fiscal',
  payment_terms_legal_reference = null,
  payment_terms_source_key      = null,
  tax_point_rule                = 'invoice_if_issued',
  tax_point_legal_reference     = 'Codul fiscal, art. 108 alin. (1) — data obligației fiscale este, ca regulă, data livrării (predarea mărfurilor, prestarea serviciului); alin. (4)-(5) — pentru servicii, sau dacă factura fiscală este eliberată ori plata este primită înainte de livrare, data obligației devine data eliberării facturii sau data plății, oricare intervine mai devreme. Principiul este livrarea, iar factura (sau plata anticipată) devansează data — exact structura pe care valoarea închisă «invoice_if_issued» o descrie; devansarea produsă exclusiv de o plată anticipată fără factură emisă anterior nu este exprimabilă separat de acest cîmp și rămîne nemodelată, ca și în cazul pachetului românesc — a se vedea secțiunea «From Moldova» din docs/international.md.',
  tax_point_source_key          = 'codul-fiscal',
  posted_edit_policy            = null,
  posted_edit_policy_legal_reference = null,
  posted_edit_policy_source_key = null,
  einvoice_profile              = null,
  einvoice_mandatory_from       = null,
  einvoice_legal_reference      = 'Codul fiscal, art. 117 alin. (12), introdus prin Legea nr. 102 din 18.06.2020 — la efectuarea livrărilor impozabile în cadrul achizițiilor publice pe teritoriul țării (inclusiv achizițiile sectoriale, concesiunile și achizițiile de valoare mică), subiectul impozabil este obligat să prezinte cumpărătorului (beneficiarului) o factură fiscală electronică prin sistemul informațional automatizat SIA „e-Factura”, cu excepția livrărilor de energie electrică, energie termică, gaze naturale, servicii comunale și servicii de comunicații electronice — obligație în vigoare de la 1 ianuarie 2021. Domeniul de aplicare a fost extins de la 1 ianuarie 2025 la livrările către agenții economici care nu au relații fiscale cu sistemul bugetar al Republicii Moldova și la mărfurile/serviciile finanțate din proiecte de asistență tehnică realizate prin granturi și tratate internaționale. `profile` rămîne vid: SIA „e-Factura” este un serviciu al Serviciul Fiscal de Stat prin care factura fiscală electronică este generată și transmisă direct în platforma de stat — cercetarea acestui pachet nu a găsit o confirmare oficială că documentul schimbat urmează un model semantic interoperabil de tipul EN 16931 (Peppol BIS, Factur-X, XRechnung, un PINT); niciun brick din packages/formats/ nu scrie, validează sau transmite azi o asemenea factură. `party_scheme` și `vat_scheme` rămîn de asemenea vide: contribuabilul este identificat prin codul fiscal (IDNO/IDNP) atribuit de Serviciul Fiscal de Stat, fără o schemă ISO 6523 înregistrată — a se vedea secțiunea «From Moldova» din docs/international.md.',
  einvoice_source_key           = 'efactura-achizitii',
  party_scheme                  = null,
  vat_scheme                    = null,
  bank_statement_formats        = null,
  payment_formats               = null,
  fiscal_year_default           = 'calendar'
 where country = 'MD';

