  (country, code, applies_when, text, text_i18n, sequence, valid_from, valid_to, legal_reference)
values
  ('MD', 'reverse_charge', 'reverse_charge', 'TVA se calculează și se achită la buget de către beneficiar, în conformitate cu art. 94 lit. c) și art. 115 din Codul fiscal.', '{"en":"VAT is calculated and paid to the budget by the recipient, in accordance with art. 94 letter c) and art. 115 of the Tax Code."}'::jsonb, 10, date '1970-01-01', null, 'Codul fiscal, art. 94 lit. c) — subiect impozabil este și persoana care importă servicii; art. 115 alin. (1) — obligația de declarare a TVA aferente serviciilor importate. Textul menționat pe factură este o formulare a acestui pachet: legea nu impune o mențiune tipizată pentru acest caz.'),
  ('MD', 'export', 'export', 'Livrare impozitată la cota zero a TVA, conform art. 104 lit. a) din Codul fiscal.', '{"en":"Supply taxed at the zero VAT rate, in accordance with art. 104 letter a) of the Tax Code."}'::jsonb, 20, date '1970-01-01', null, 'Codul fiscal, art. 104 lit. a) — mărfurile, serviciile pentru export și toate tipurile de transporturi internaționale de mărfuri și pasageri se impozitează la cota zero a TVA.'),
  ('MD', 'exempt', 'exempt', 'Livrare scutită de TVA fără drept de deducere, conform art. 103 din Codul fiscal.', '{"en":"Supply exempt from VAT without the right of deduction, in accordance with art. 103 of the Tax Code."}'::jsonb, 30, date '1970-01-01', null, 'Codul fiscal, art. 103 alin. (1) — T.V.A. nu se aplică livrărilor enumerate la acest alineat, printre care, la pct. 1), locuința, pămîntul, arenda acestora.')
on conflict (country, code) do update set
  applies_when    = excluded.applies_when,
  text            = excluded.text,
  text_i18n       = excluded.text_i18n,
  sequence        = excluded.sequence,
  valid_from      = excluded.valid_from,
  valid_to        = excluded.valid_to,
  legal_reference = excluded.legal_reference;
